def minGroupsForValidAssignment(nums: list[int]) -> int:
    """
    Given a 0-indexed integer array nums of length n.
    We want to group the indices so for each index i in the range [0, n - 1], it is assigned to exactly one group.
    A group assignment is valid if the following conditions hold:

    For every group g, all indices i assigned to group g have the same value in nums.
    For any two groups g_1 and g_2, the difference between the number of indices assigned to g_1 and g_2 should not exceed 1.

    Return an integer denoting the minimum number of groups needed to create a valid group assignment.
    """
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    frequencies = list(counts.values())
    frequencies.sort()

    def check(group_size):
        groups = 0
        for freq in frequencies:
            num_groups = freq // (group_size + 1)
            remainder = freq % (group_size + 1)

            if remainder > 0 and remainder < freq // (group_size + 1):
                return float('inf')



            if remainder > 0:
               if remainder > group_size:
                   return float('inf')


            if freq % (group_size + 1) == 0:
                num_groups = freq // (group_size + 1)

            if freq % (group_size + 1) > 0:
                 num_groups = freq // (group_size + 1) + 1
            groups += num_groups

        return groups

    left, right = 1, len(nums)
    ans = float('inf')
    while left <= right:
        mid = (left + right) // 2

        num_groups = check(mid)

        if num_groups != float('inf'):
            ans = min(ans, num_groups)
            right = mid - 1
        else:
            left = mid + 1

    return ans
